@AssertTrue(message = "reorderWindow must be positive") public boolean isReorderWindowPositive() {
    return reorderWindow == null || reorderWindow.compareTo(Duration.ZERO) > 0;
}

@AssertTrue(message = "boundary keys must be lower-case and boundaries non-null") public boolean isBoundariesWellFormed() {
    return boundaries == null || boundaries.entrySet().stream().allMatch(entry -> entry.getKey() != null && entry.getValue() != null && entry.getKey().equals(entry.getKey().toLowerCase(Locale.ROOT)));
}

public record Window(@NotNull Duration size, @NotNull Duration slide) {
    @AssertTrue(message = "size and slide must be positive")
    public boolean isPositive() {
        return size == null || slide == null || (size.compareTo(Duration.ZERO) > 0 && slide.compareTo(Duration.ZERO) > 0);
    }

    @AssertTrue(message = "size must be greater than or equal to slide")
    public boolean isSizeAtLeastSlide() {
        return size == null || slide == null || size.compareTo(slide) >= 0;
    }
}

public record Boundary(Double min, Double max) {
    @AssertTrue(message = "min must be less than or equal to max")
    public boolean isOrdered() {
        return min == null || max == null || min <= max;
    }
}
